// ---------- Extended notification types ----------

type ExtendedNotifType =
  | "match"
  | "like"
  | "message"
  | "event"
  | "challenge"
  | "system"
  | "review"
  | "feed";

interface NotificationItem {
  id: string;
  type: ExtendedNotifType;
  title: string;
  body: string;
  timestamp: string;
  read: boolean;
  data: Record<string, unknown>;
}

// ---------- Filter tabs ----------

type FilterTab = "all" | "matchs" | "messages" | "system";

const TABS: { key: FilterTab; label: string }[] = [
  { key: "all", label: "Toutes" },
  { key: "matchs", label: "Matchs" },
  { key: "messages", label: "Messages" },
  { key: "system", label: "Systeme" },
];

function getFilterTypes(tab: FilterTab): ExtendedNotifType[] | null {
  switch (tab) {
    case "all":
      return null;
    case "matchs":
      return ["match", "like"];
    case "messages":
      return ["message"];
    case "system":
      return ["system", "challenge", "event", "review", "feed"];
  }
}

