}

// --- Main page ---

export default function RoomsPage() {
  const [activeCategory, setActiveCategory] = useState<RoomCategory>("tous");
  const { rooms: dbRooms, loading } = useRooms();

  // Map DB rooms to MockRoom shape (UI contract), fall back to mock if empty
  const liveRooms: MockRoom[] = useMemo(() => {
    if (dbRooms.length === 0) return MOCK_ROOMS;
    return dbRooms.map((r: Room): MockRoom => {
      const m = modeMeta(r.mode);
      return {
        id: r.id,
        title: r.title,
        host: {
          name: r.hostName,
          avatar: r.hostAvatar ?? `https://i.pravatar.cc/150?u=${r.hostId}`,
        },
        speakers: [],
        listenerCount: r.currentListeners,
        category: m.category,
        modeLabel: m.label,
        modeColor: m.color,
        modeIcon: m.icon,
        startedMinutesAgo: minutesSince(r.startedAt),
      };
    });
  }, [dbRooms]);

  const filteredRooms = useMemo(() => {
    if (activeCategory === "tous") return liveRooms;
    return liveRooms.filter((r) => r.category === activeCategory);
  }, [activeCategory, liveRooms]);

  return (
    <div className="min-h-screen bg-bg pb-28">
      {/* Header */}
      <header className="sticky top-0 z-40 bg-bg/95 backdrop-blur-md border-b border-border px-5 pt-3 pb-3">
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
        >
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-2">
              <span className="text-lg" aria-hidden="true">
                {"\uD83C\uDF99\uFE0F"}
              </span>
              <h1 className="text-base font-display font-bold text-text">
                Salons vocaux
              </h1>
              <span className="text-[10px] text-accent/70 font-medium ml-1">
                {loading ? "..." : `${liveRooms.length} live`}
              </span>
            </div>
            <motion.button
              whileHover={{
                scale: 1.05,
                boxShadow: "0 0 15px rgba(139,92,246,0.4)",
              }}
              whileTap={{ scale: 0.92 }}
              className="inline-flex items-center gap-1 px-3 py-1.5 rounded-full gradient-bg text-white text-[11px] font-bold shadow-glow"
            >
              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.5"
                strokeLinecap="round"
                aria-hidden="true"
              >
                <line x1="12" y1="5" x2="12" y2="19" />
                <line x1="5" y1="12" x2="19" y2="12" />
              </svg>
              Creer
            </motion.button>
          </div>
        </motion.div>

        {/* Category tabs */}
        <div className="flex gap-1.5 mt-2">
          {CATEGORIES.map((cat) => (
            <motion.button
              key={cat.key}
              onClick={() => setActiveCategory(cat.key)}
              whileTap={{ scale: 0.92 }}
              className={`px-3 py-1.5 rounded-full text-[11px] font-semibold border tap-target transition-all ${
                activeCategory === cat.key
                  ? "border-accent gradient-bg text-white"
                  : "border-border text-text-muted"
              }`}
            >
              {cat.label}
            </motion.button>
          ))}
        </div>
      </header>

      {/* Rooms list */}
      {filteredRooms.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 px-6 text-center">
          <div className="w-16 h-16 rounded-full bg-card border border-border flex items-center justify-center mb-4">
            <svg
              width="28"
              height="28"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              className="text-text-muted"
              aria-hidden="true"
            >
              <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
              <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
              <line x1="12" y1="19" x2="12" y2="23" />
              <line x1="8" y1="23" x2="16" y2="23" />
            </svg>
          </div>
          <p className="text-sm font-semibold text-text-muted">
            Aucun salon dans cette categorie
          </p>
          <p className="text-xs text-text-muted mt-1">
            Sois le premier a lancer la conversation!
          </p>
        </div>
      ) : (
        <motion.div
          className="px-4 pt-3 space-y-3"
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          role="list"
          aria-label="Liste des salons vocaux"
        >
          <AnimatePresence mode="popLayout">
            {filteredRooms.map((room) => (
              <motion.div
                key={room.id}
                variants={cardVariants}
                layout
                role="listitem"
              >
                <RoomCard room={room} />
              </motion.div>
            ))}
          </AnimatePresence>
        </motion.div>
      )}
    </div>
  );
}

