import { supabase } from "@/lib/supabase";
import { RackFocus } from "@/components/motion/RackFocus";
import EmptyState from "@/components/ui/EmptyState";

// --- Types ---

interface Venue {
  id: string;
  name: string;
  type: string;
  neighborhood: string;
  distance: number;
