-- Migration 009 : Performance tuning
-- Audit ARCH_BACKEND_2026-04-19 : DB-2 (auth_rls_initplan) + DB-6 (unindexed FK) + DB-7 (unused indexes)
-- Generated by API+Hooks Unification Architect subagent.

BEGIN;

-- ---------------------------------------------------------------
-- Section A: DB-2 Fix auth_rls_initplan (55 policies)
-- Wrap auth.uid() in (select ...) so Postgres computes initPlan once
-- per query instead of per row.
-- ---------------------------------------------------------------

DROP POLICY IF EXISTS "Users manage own achievements" ON public.achievements;
CREATE POLICY "Users manage own achievements" ON public.achievements
  FOR ALL
  TO public
  USING (((select auth.uid()) = user_id));

DROP POLICY IF EXISTS "Users manage own availability" ON public.availability;
CREATE POLICY "Users manage own availability" ON public.availability
  FOR ALL
  TO public
  USING (((select auth.uid()) = user_id));

DROP POLICY IF EXISTS "Users manage own challenges" ON public.challenges;
CREATE POLICY "Users manage own challenges" ON public.challenges
  FOR ALL
  TO public
  USING (((select auth.uid()) = user_id));

DROP POLICY IF EXISTS "Users see own challenges" ON public.challenges;
CREATE POLICY "Users see own challenges" ON public.challenges
  FOR SELECT
  TO public
  USING (((select auth.uid()) = user_id));

DROP POLICY IF EXISTS "Users manage own checkins" ON public.checkins;
CREATE POLICY "Users manage own checkins" ON public.checkins
  FOR ALL
  TO public
  USING (((select auth.uid()) = user_id));

DROP POLICY IF EXISTS "Users see own checkins" ON public.checkins;
CREATE POLICY "Users see own checkins" ON public.checkins
  FOR SELECT
  TO public
  USING (((select auth.uid()) = user_id));

DROP POLICY IF EXISTS "Conversation participants" ON public.conversations;
CREATE POLICY "Conversation participants" ON public.conversations
  FOR SELECT
  TO public
  USING ((((select auth.uid()) = user_a) OR ((select auth.uid()) = user_b)));

DROP POLICY IF EXISTS "Users create conversations" ON public.conversations;
CREATE POLICY "Users create conversations" ON public.conversations
  FOR INSERT
  TO public
  WITH CHECK ((((select auth.uid()) = user_a) OR ((select auth.uid()) = user_b)));

