                    <input
                      id="reg-name"
                      type="text"
                      required
                      placeholder="Ton prenom"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      autoComplete="given-name"
                      className="w-full px-3 py-3 rounded-xl text-sm placeholder:text-white/30 focus:outline-none"
                      style={INPUT_STYLE}
