                  CGU
                </Link>{" "}
                et notre{" "}
                <Link
                  href="/privacy"
                  className="underline"
                  style={{ color: landing.violet }}
                >
                  Politique de confidentialite
                </Link>
                .
              </p>
            </motion.div>
          )}

          {/* Step 3 â€” photo */}
          {step === 3 && tempUserId && (
            <motion.div
              key="step3"
              variants={stepVariants}
              initial="enter"
              animate="center"
              exit="exit"
            >
              <h1 className="font-display text-2xl font-bold mb-1 tracking-tight">
