                  </button>
                  <Magnetic as="div" strength={0.12} radius={120} className="flex-1">
                    <motion.button
                      type="submit"
                      whileHover={{
                        y: -2,
                        boxShadow: "0 14px 60px rgba(0,255,136,0.35)",
