        </AnimatePresence>

        <p className="text-sm text-white/60 text-center mt-6">
          Deja inscrit ?{" "}
          <Link
            href="/login"
            className="font-semibold transition-opacity hover:opacity-80"
            style={{ color: landing.vert }}
          >
            Se connecter
          </Link>
        </p>
      </motion.div>
    </main>
  );
